"""Original synthetic paraphrase families and independently combined context surfaces.
No external text, no model replies or private messages. Eval forms are public development holdouts.
Each family deliberately has stable targets: variants are related views, not independent stories.
"""
import hashlib,json,itertools

def make(parts,family,split='train',kind='template'):
    r={'messages':[{'role':'user' if i%2==0 else 'assistant','content':v}for i,v in enumerate(parts)],
       'family':'v22_'+family,'split':split,'origin':'authored-'+kind+'-v22'}
    r['id']='ru-v22-'+hashlib.sha256(json.dumps(r['messages'],ensure_ascii=False,sort_keys=True).encode()).hexdigest()[:20]
    return r

